    {"id": "T2", "group": "T", "cls": "fetch", "consequence": "Lucinid bivalves absent -> sulphide detoxification lost", "blocker": "**infaunal bivalve records within seagrass beds are in ODA bundfauna if anyone looks**"},
    {"id": "T3", "group": "T", "cls": "experiment", "consequence": "Labyrinthula virulence rises with host stress", "blocker": "Labyrinthula screening in Danish eelgrass; not routine"},
    {"id": "T4", "group": "T", "cls": "experiment", "consequence": "Replanting fails on conditioned sediment and succeeds on clean", "blocker": "**restoration trials with sediment treatments.** A handful of Danish eelgrass trials exist; this design does not"},
    {"id": "T5", "group": "T", "cls": "experiment", "consequence": "Suppressive sediment resists invasion; degraded does not", "blocker": "sediment microbial composition **and transfer experiments** — neither exists"},
    {"id": "T6", "group": "T", "cls": "experiment", "consequence": "Enrichment dissolves the partnership by making it unnecessary", "blocker": "rhizosphere community composition along the gradient"},
    {"id": "T7", "group": "T", "cls": "experiment", "consequence": "Anaerobic phytotoxins beyond sulphide", "blocker": "porewater chemistry beyond the standard nutrients"},
    {"id": "T8", "group": "T", "cls": "unscoreable", "consequence": "Anaerobia selects for the pathogens", "blocker": "**essentially no marine oomycete or labyrinthulid surveys**"},
    {"id": "T9", "group": "T", "cls": "unscoreable", "consequence": "Pathogen and partner are not kinds of organism", "blocker": "host-associated microbial and viral community data through a stress gradient — **absent for every Danish marine species**"},
    {"id": "T12", "group": "T", "cls": "unscoreable", "consequence": "Defence is outsourced; a biocide disarms the host", "blocker": "host-associated community data with matched disease outcomes — absent"},
    {"id": "T11", "group": "T", "cls": "experiment", "consequence": "Occupancy is the function; the empty niche is the risk", "blocker": "**challenge experiments on intact versus disturbed communities.** Standard in medical and soil microbiology, not applied in Danish marine work"},
    {"id": "T10", "group": "T", "cls": "unscoreable", "consequence": "Removing an unknown-role organism is not neutral", "blocker": "**baseline composition before intervention is almost never collected**, which makes the comparison impossible by construction"},
