    {"id": "S2", "group": "S", "cls": "fetch", "consequence": "Legacy soil P leaks after inputs stop", "blocker": "**Denmark holds soil P status and it is not carried into the marine argument** — a fetch and a join"},
    {"id": "S3", "group": "S", "cls": "experiment", "consequence": "Sorption is hysteretic — a ratchet on the land side too", "blocker": "sorption-desorption experiments on Danish soils; standard method"},
    {"id": "S4", "group": "S", "cls": "fetch", "consequence": "Total P is not available P", "blocker": "fractionated sediment P — sedimentkemi `Emne_12_19` carries Fe-adsorbed P at {was:4469fc7:docs/hypodrafts/TRIAGE.md:Fe-adsorbed P at @@ | | **S5**}"},
    {"id": "S5", "group": "S", "cls": "resolution", "consequence": "Buffering scales with the volume of reactive medium", "blocker": "bathymetry is held; **sediment thickness is not**"},
    {"id": "S6", "group": "S", "cls": "testable", "consequence": "The retention coefficient is not constant — it saturates", "blocker": "the register's own Needs line: **'Requires no new measurement at all'** — the same catchment flux data split by period. Blocked only insofar as the flux series is the unfetched input"},
    {"id": "R11", "group": "R", "cls": "unscoreable", "consequence": "Marine fungi decompose and nobody counts them", "blocker": "**essentially no marine fungal surveys in Danish waters**"},
